module VexiiCVW_DivRadix (
  input  wire          io_flush,
  input  wire          io_cmd_valid,
  output wire          io_cmd_ready,
  input  wire [55:0]   io_cmd_payload_a,
  input  wire [55:0]   io_cmd_payload_b,
  input  wire          io_cmd_payload_normalized,
  input  wire [5:0]    io_cmd_payload_iterations,
  output wire          io_rsp_valid,
  input  wire          io_rsp_ready,
  output wire [55:0]   io_rsp_payload_result,
  output wire [55:0]   io_rsp_payload_remain,
  input  wire          clk,
  input  wire          reset
);

  wire       [13:0]   _zz_shifter_1;
  wire       [27:0]   _zz_shifter_2;
  wire       [41:0]   _zz_shifter_3;
  wire       [54:0]   _zz_shifter_4;
  reg        [5:0]    counter;
  reg                 busy;
  wire                io_rsp_fire;
  reg                 done;
  wire                when_DivRadix_l45;
  reg        [55:0]   shifter;
  reg        [55:0]   numerator;
  reg        [55:0]   result;
  reg        [56:0]   div1;
  reg        [56:0]   div3;
  wire       [56:0]   div2;
  wire       [56:0]   shifted;
  wire       [57:0]   sub1;
  wire                when_DivRadix_l64;
  reg        [56:0]   _zz_shifter;
  wire                when_DivRadix_l68;
  wire                slicesZero_0;
  wire                slicesZero_1;
  wire                slicesZero_2;
  wire       [2:0]    shiftSel;
  wire       [3:0]    _zz_sel;
  wire                _zz_sel_1;
  wire                _zz_sel_2;
  wire                _zz_sel_3;
  reg        [3:0]    _zz_sel_4;
  wire       [3:0]    _zz_sel_5;
  wire                _zz_sel_6;
  wire                _zz_sel_7;
  wire                _zz_sel_8;
  wire       [1:0]    sel;
  reg                 wasBusy;
  wire                when_DivRadix_l93;

  assign _zz_shifter_1 = io_cmd_payload_a[55 : 42];
  assign _zz_shifter_2 = io_cmd_payload_a[55 : 28];
  assign _zz_shifter_3 = io_cmd_payload_a[55 : 14];
  assign _zz_shifter_4 = io_cmd_payload_a[55 : 1];
  assign io_rsp_fire = (io_rsp_valid && io_rsp_ready);
  assign when_DivRadix_l45 = (busy && (counter == 6'h37));
  assign div2 = (div1 <<< 1);
  assign shifted = {shifter,numerator[55 : 55]};
  assign sub1 = ({1'b0,shifted} - {1'b0,div1});
  assign io_rsp_valid = done;
  assign io_rsp_payload_result = result;
  assign io_rsp_payload_remain = shifter;
  assign io_cmd_ready = (! busy);
  assign when_DivRadix_l64 = (! done);
  always @(*) begin
    _zz_shifter = shifted;
    if(when_DivRadix_l68) begin
      _zz_shifter = sub1[56:0];
    end
  end

  assign when_DivRadix_l68 = (! sub1[57]);
  assign slicesZero_0 = (io_cmd_payload_a[27 : 14] == 14'h0);
  assign slicesZero_1 = (io_cmd_payload_a[41 : 28] == 14'h0);
  assign slicesZero_2 = (io_cmd_payload_a[55 : 42] == 14'h0);
  assign shiftSel = {(&slicesZero_2),(&{slicesZero_2,slicesZero_1}),(&{slicesZero_2,slicesZero_1,slicesZero_0})};
  assign _zz_sel = {1'b1,shiftSel};
  assign _zz_sel_1 = _zz_sel[0];
  assign _zz_sel_2 = _zz_sel[1];
  assign _zz_sel_3 = _zz_sel[2];
  always @(*) begin
    _zz_sel_4[0] = (_zz_sel_1 && (! 1'b0));
    _zz_sel_4[1] = (_zz_sel_2 && (! _zz_sel_1));
    _zz_sel_4[2] = (_zz_sel_3 && (! (|{_zz_sel_2,_zz_sel_1})));
    _zz_sel_4[3] = (_zz_sel[3] && (! (|{_zz_sel_3,_zz_sel_2,_zz_sel_1})));
  end

  assign _zz_sel_5 = _zz_sel_4;
  assign _zz_sel_6 = _zz_sel_5[3];
  assign _zz_sel_7 = (_zz_sel_5[1] || _zz_sel_6);
  assign _zz_sel_8 = (_zz_sel_5[2] || _zz_sel_6);
  assign sel = {_zz_sel_8,_zz_sel_7};
  assign when_DivRadix_l93 = (! busy);
  always @(posedge clk or posedge reset) begin
    if(reset) begin
      busy <= 1'b0;
      done <= 1'b0;
      wasBusy <= 1'b0;
    end else begin
      if(io_rsp_fire) begin
        busy <= 1'b0;
      end
      if(when_DivRadix_l45) begin
        done <= 1'b1;
      end
      if(io_rsp_fire) begin
        done <= 1'b0;
      end
      wasBusy <= busy;
      if(when_DivRadix_l93) begin
        busy <= io_cmd_valid;
      end
      if(io_flush) begin
        done <= 1'b0;
        busy <= 1'b0;
      end
    end
  end

  always @(posedge clk) begin
    if(when_DivRadix_l64) begin
      counter <= (counter + 6'h01);
      result <= (result <<< 1);
      if(when_DivRadix_l68) begin
        result[0 : 0] <= 1'b1;
      end
      shifter <= _zz_shifter[55:0];
      numerator <= (numerator <<< 1);
    end
    if(when_DivRadix_l93) begin
      div1 <= {1'd0, io_cmd_payload_b};
      result <= ((io_cmd_payload_b == 56'h0) ? 56'hffffffffffffff : 56'h0);
      case(sel)
        2'b11 : begin
          counter <= 6'h0;
          shifter <= 56'h0;
          numerator <= (io_cmd_payload_a <<< 0);
        end
        2'b10 : begin
          counter <= 6'h0e;
          shifter <= {42'd0, _zz_shifter_1};
          numerator <= (io_cmd_payload_a <<< 14);
        end
        2'b01 : begin
          counter <= 6'h1c;
          shifter <= {28'd0, _zz_shifter_2};
          numerator <= (io_cmd_payload_a <<< 28);
        end
        default : begin
          counter <= 6'h2a;
          shifter <= {14'd0, _zz_shifter_3};
          numerator <= (io_cmd_payload_a <<< 42);
        end
      endcase
      if(io_cmd_payload_normalized) begin
        counter <= (6'h37 - io_cmd_payload_iterations);
        shifter <= {1'd0, _zz_shifter_4};
        numerator <= (io_cmd_payload_a <<< 55);
      end
    end
  end


endmodule

